-- PEP(人教版)20 册词库迁移:0 → 5049 词/册次 × 3 active 课程 = 15147 word 行
-- 教材:小学三起点 8 册 + 初中 5 册 + 高中 2019 版 7 册
-- 词表来源:cyforkk/pep-english-words (MIT) 单元 → 单词 JSON
-- 字段策略:KET 重叠词复用 KET tuple(校园语境),TOEIC-only 重叠复用 TOEIC,净新词 LLM 生成
-- 共 4132 去重词(其中 2184 与 KET/TOEIC 重叠 → 自动复用 lexeme_id;净新 1948 词)
-- 幂等:courses WHERE NOT EXISTS;lexicon ON CONFLICT DO NOTHING;words WHERE NOT EXISTS
-- 旧 24 个占位英语教材(小学一/二年级上下、初中九年级上下、高中高一-高三上下)保持 inactive 不动

