-- 2. 确保 20 PEP 教材的 朗读/学习/测评 三门 active
UPDATE courses SET is_active = TRUE, updated_at = NOW()
WHERE subject = '英语' AND textbook IN (
'小学人教版三年级上',
'小学人教版三年级下',
'小学人教版四年级上',
'小学人教版四年级下',
'小学人教版五年级上',
