('高中人教版选择性必修四', 'olivia', '["olivia"]', '奥利维娅（女子名）', '/əˈlɪv.i.ə/', 'Olivia sings English songs very well.', '奥利维娅英文歌唱得很好。', 287),
('高中人教版选择性必修四', 'pets', '["pets"]', '宠物(pet 的复数)', '/pets/', 'Many families keep pets like cats and dogs.', '许多家庭养猫狗之类的宠物。', 288)
) AS v(textbook, spelling, syllables, meaning_cn, phonetic, sample_sentence, sample_sentence_translation, sort_order)
JOIN courses c ON c.subject = '英语' AND c.textbook = v.textbook
                AND c.learning_method IN ('朗读', '学习', '测评') AND c.is_active = TRUE
JOIN lexicon l ON l.spelling = v.spelling
WHERE NOT EXISTS (SELECT 1 FROM words x WHERE x.course_id = c.id AND x.spelling = v.spelling);
